import java.util.*;

class Solution {
  private final Set<TreeNode> seen = new HashSet<>();

  public TreeNode correctBinaryTree(TreeNode root) {
    // visiting right before left, the bad node's right pointer reaches an already-visited node
    if (root == null) return null;
    if (root.right != null && seen.contains(root.right)) return null;
    seen.add(root);
    root.right = correctBinaryTree(root.right);
    root.left = correctBinaryTree(root.left);
    return root;
  }
}
